package cn.binbin.crm;
import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import static cn.binbin.crm.TradeService.*;import static cn.binbin.crm.P3Base.map;
@Service
public class PublicIntakeService {
 public record Create(@NotBlank @Size(max=100) String name,@NotNull @Pattern(regexp="LEAD|TICKET") String entityType,@NotNull UUID ownerMemberId,@Min(1) @Max(365) int expiresDays){}
 public record Submission(@NotBlank @Size(max=100) String name,@Size(max=200) String companyName,@Size(max=40) @Pattern(regexp="[0-9+().\\-\\s]*") String phone,@jakarta.validation.constraints.Email @Size(max=254) String email,@NotBlank @Size(max=4000) String message,boolean consent,@Size(max=80) String website){}
 private final P7Records r;private final P3Base b;private final P7Permissions p;
 public PublicIntakeService(P7Records r,P7Permissions p){this.r=r;this.b=r.b;this.p=p;}
 private long epoch(AuthService.Actor a){return b.db.queryForObject("SELECT auth_version FROM iam_user WHERE id=:id",map("id",a.session().userId()),Long.class);}
 public Object list(AuthService.Session s){return b.tx.execute(st->{var a=b.auth.actor(s);p.admin(a);return map("items",b.rows("SELECT id,name,entity_type,owner_member_id,active,expires_at,version,created_at FROM crm_public_form WHERE tenant_id=:tenant ORDER BY created_at DESC,id",map("tenant",a.tenant().id())),"plan",SaasService.view(p.plan(a)));});}
 public Object create(AuthService.Session s,Create i,UUID trace){return b.tx.execute(st->{b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",s.tenantId()),UUID.class);var a=b.auth.actor(s);p.admin(a);p.feature(a,"workspace");var owner=b.actor(a.tenant().id(),i.ownerMemberId());if(!r.allowed(a,i.entityType(),true)||!r.allowed(owner,i.entityType(),true))throw ApiError.forbidden("配置者与归属成员需有对应业务写入权限");p.quota(a,"public_form_limit",b.db.queryForObject("SELECT count(*) FROM crm_public_form WHERE tenant_id=:tenant AND active AND expires_at>now()",map("tenant",a.tenant().id()),Long.class));UUID id=UUID.randomUUID();String token=a.tenant().id()+"."+Crypto.token();b.db.update("INSERT INTO crm_public_form(id,tenant_id,name,entity_type,owner_member_id,creator_member_id,owner_auth_version,token_hash,expires_at) VALUES(:id,:tenant,:name,:type,:owner,:creator,:epoch,:token,:expires)",map("id",id,"tenant",a.tenant().id(),"name",text(i.name()),"type",i.entityType(),"owner",i.ownerMemberId(),"creator",a.tenant().memberId(),"epoch",epoch(owner),"token",Crypto.hash(token),"expires",Instant.now().plusSeconds(i.expiresDays()*86400L)));b.audit(a,"PUBLIC_FORM_CREATED","PUBLIC_FORM",id,0,trace);return map("id",id,"oneTimeToken",token,"path","/?intake="+token);});}
 public Object revoke(AuthService.Session s,UUID id,long expected,UUID trace){return b.tx.execute(st->{var a=b.auth.actor(s);p.admin(a);p.feature(a,"workspace");if(b.db.update("UPDATE crm_public_form SET active=false,version=version+1 WHERE tenant_id=:tenant AND id=:id AND version=:version",map("tenant",a.tenant().id(),"id",id,"version",expected))!=1)throw ApiError.conflict("表单已变化，请刷新");b.audit(a,"PUBLIC_FORM_REVOKED","PUBLIC_FORM",id,expected+1,trace);return map("revoked",true);});}
 private UUID tenant(String token){if(token==null||!token.matches("[a-f0-9-]{36}\\.[A-Za-z0-9_-]{43}"))throw ApiError.missing();try{return UUID.fromString(token.substring(0,36));}catch(Exception e){throw ApiError.missing();}}
 private Map<String,Object> form(UUID tenant,String token){b.context(tenant);var f=b.one("SELECT * FROM crm_public_form WHERE tenant_id=:tenant AND token_hash=:hash AND active AND expires_at>now()",map("tenant",tenant,"hash",Crypto.hash(token)));var owner=b.actor(tenant,(UUID)f.get("ownerMemberId"));var creator=b.actor(tenant,(UUID)f.get("creatorMemberId"));p.admin(creator);p.feature(owner,"workspace");if(epoch(owner)!=number(f,"ownerAuthVersion")||!r.allowed(owner,(String)f.get("entityType"),true)||!r.allowed(creator,(String)f.get("entityType"),true))throw ApiError.missing();return f;}
 public Object describe(String token){UUID tenant=tenant(token);return b.tx.execute(st->{var f=form(tenant,token);return map("name",f.get("name"),"entityType",f.get("entityType"),"expiresAt",f.get("expiresAt"),"consentRequired",true);});}
 public Object submit(String token,Submission i,String key,String client,UUID trace){UUID tenant=tenant(token);if(text(i.phone()).isEmpty()&&text(i.email()).isEmpty())throw ApiError.bad("电话或邮箱至少填写一项");if(!i.consent()||!text(i.website()).isEmpty())throw ApiError.bad("请确认联系授权后提交");if(key==null||!key.matches("[A-Za-z0-9_-]{16,80}"))throw ApiError.bad("请使用有效提交编号");return b.tx.execute(st->{b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",tenant),UUID.class);var f=form(tenant,token);var owner=b.actor(tenant,(UUID)f.get("ownerMemberId"));var args=map("tenant",tenant,"form",f.get("id"),"key",key,"hash",Crypto.hash(b.json(i)),"fingerprint",Crypto.hash(String.valueOf(f.get("id"))+":"+client));var old=b.rows("SELECT id,request_hash FROM crm_public_submission WHERE tenant_id=:tenant AND form_id=:form AND request_key=:key",args);if(!old.isEmpty()){if(!args.get("hash").equals(old.getFirst().get("requestHash")))throw ApiError.conflict("提交编号已用于其他资料");return map("receiptId",old.getFirst().get("id"),"message","已收到，请等待工作人员联系");}if(b.db.queryForObject("SELECT count(*) FROM crm_public_submission WHERE tenant_id=:tenant AND form_id=:form AND fingerprint=:fingerprint AND created_at>now()-interval '1 hour'",args,Integer.class)>=10)throw new ApiError(org.springframework.http.HttpStatus.TOO_MANY_REQUESTS,"PUBLIC_FORM_RATE_LIMIT","提交过于频繁，请稍后再试");p.quota(owner,"public_submission_monthly_limit",b.db.queryForObject("SELECT count(*) FROM crm_public_submission WHERE tenant_id=:tenant AND created_at>=date_trunc('month',now() AT TIME ZONE 'Asia/Shanghai') AT TIME ZONE 'Asia/Shanghai'",args,Long.class));UUID record;if("LEAD".equals(f.get("entityType"))){if(text(i.companyName()).isEmpty())throw ApiError.bad("请填写公司名称");var lead=r.business.createLead(owner.session(),new BusinessService.LeadCreate(text(i.name()),text(i.companyName()),"待确认","外链表单","","",text(i.phone()),text(i.email()),text(i.message()),owner.tenant().memberId()),"form:"+f.get("id")+":"+Crypto.hash(key).substring(0,20),trace);record=lead.id();}else{var ticket=r.object(r.desk.create(owner.session(),new ServiceDeskService.TicketInput("客户咨询 · "+text(i.name()),"联系电话："+text(i.phone())+"\n"+text(i.message()),null,owner.tenant().memberId(),"NORMAL",null,text(i.name()),text(i.email()),0,"GENERAL"),"form:"+f.get("id")+":"+Crypto.hash(key).substring(0,20),trace));record=UUID.fromString(String.valueOf(ticket.get("id")));}UUID receipt=UUID.randomUUID();args.putAll(map("id",receipt,"record",record));b.db.update("INSERT INTO crm_public_submission(id,tenant_id,form_id,request_key,request_hash,fingerprint,entity_id) VALUES(:id,:tenant,:form,:key,:hash,:fingerprint,:record)",args);b.audit(owner,"PUBLIC_FORM_SUBMITTED",(String)f.get("entityType"),record,0,trace);return map("receiptId",receipt,"message","已收到，请等待工作人员联系");});}
}
